// Normalizes a raw provider response into the internal stock-universe row shape:
// { symbol, name, isin, sector, exchange, currency, _valid, errors[] }
// Tolerant of shape differences between providers (array directly, or wrapped in
// a "data"/"symbols" property) since the exact provider contract varies.
//
// IMPORTANT: n8n's HTTP Request node auto-splits a top-level JSON ARRAY
// response into one item per element — confirmed via live E2E testing
// against EODHD's exchange-symbol-list endpoint (241 real tickers arrived
// as 241 separate items, not one item holding a 241-element array). Must
// use $input.all(), not $input.first().
const exchange = $env.EGX_EXCHANGE_CODE || 'EGX';
const items = $input.all().map((i) => i.json);

function looksLikeSymbolRecord(v) {
  return v && typeof v === 'object' && !Array.isArray(v)
    && (v.Code || v.symbol || v.Symbol || v.ticker);
}

let list;
if (items.length > 1 || looksLikeSymbolRecord(items[0])) {
  // Auto-split case: every item IS already one symbol object (also covers
  // the single-ticker edge case, detected by shape rather than count).
  list = items;
} else {
  // Single-item case wrapping an array, e.g. { data: [...] }.
  const raw = items[0];
  list = raw;
  if (!Array.isArray(list)) {
    list = (raw && (raw.data || raw.symbols || raw.results)) || [];
  }
}
if (!Array.isArray(list)) {
  throw new Error('Provider response for the stock universe was not a recognizable list. Check the HTTP Request node URL/response shape.');
}

const rows = list.map((entry) => {
  const symbol = entry.Code || entry.symbol || entry.Symbol || entry.ticker || null;
  const name = entry.Name || entry.name || entry.CompanyName || null;
  const isin = entry.Isin || entry.isin || null;
  const sector = entry.Sector || entry.sector || null;
  const currency = entry.Currency || entry.currency || 'EGP';

  const errors = [];
  if (!symbol || typeof symbol !== 'string') errors.push('missing/invalid symbol');
  if (!name || typeof name !== 'string') errors.push('missing/invalid name');

  return {
    symbol: symbol ? String(symbol).trim().toUpperCase() : null,
    name: name ? String(name).trim() : null,
    isin: isin || null,
    sector: sector || null,
    exchange,
    currency,
    _valid: errors.length === 0,
    errors,
  };
});

// De-duplicate by symbol, keeping the last occurrence.
const bySymbol = new Map();
for (const row of rows) {
  const key = row.symbol || `__invalid_${Math.random()}`;
  bySymbol.set(key, row);
}

return Array.from(bySymbol.values()).map((json) => ({ json }));

const count = $input.first().json.active_stock_count;
return [{ json: {
  workflow: '01-egx-stock-universe',
  finishedAt: new Date().toISOString(),
  activeStockCount: count,
  message: `Stock universe refreshed. ${count} active EGX stocks.`,
} }];
